/* @lc app=leetcode id=3260 lang=kotlin */ class Solution { fun largestPalindrome(n: Int, k: Int): String = if (k == 1 || k == 3 || k == 9) "9".repeat(n) else if (k == 2) (if (n <= 2) "8".repeat(n) else "8" + "9".repeat(n - 2) + "8") else if (k == 4) (if (n <= 4) "8".repeat(n) else "88" + "9".repeat(n - 4) + "88") else if (k == 5) (if (n <= 2) "5".repeat(n) else "5" + "9".repeat(n - 2) + "5") else if (k == 8) (if (n <= 6) "8".repeat(n) else "888" + "9".repeat(n - 6) + "888") else if (k == 6) (if (n <= 2) "6".repeat(n) else if (n % 2 == 1) "8" + "9".repeat((n - 3) / 2) + "8" + "9".repeat((n - 3) / 2) + "8" else "8" + "9".repeat((n - 4) / 2) + "77" + "9".repeat((n - 4) / 2) + "8") else (n / 2).let { m -> java.math.BigInteger.valueOf(10).let { t -> java.math.BigInteger.valueOf(7).let { sv -> ((if (n % 2 == 1) t.modPow(java.math.BigInteger.valueOf(m.toLong()), sv).toInt() else 11 * t.modPow(java.math.BigInteger.valueOf(m - 1L), sv).toInt() % 7) % 7).let { w -> ((t.modPow(java.math.BigInteger.valueOf(n.toLong()), sv).toInt() + 6) % 7).let { base -> (0..6).first { it * w % 7 == base }.let { e -> if (n % 2 == 1) "9".repeat(m) + (9 - e) + "9".repeat(m) else "9".repeat(m - 1) + (9 - e) + (9 - e) + "9".repeat(m - 1) } } } } } } }